Below is a compact, self‑contained example that shows **operator overloading** in C++.
We implement a tiny `Rational` class (a rational number *numerator/denominator*) and overload a handful of operators:

| Operator | Where it’s defined | What it does |
|----------|--------------------|--------------|
| `+ - * /` | **member** functions | Binary arithmetic |
| `+= -= *= /=` | **member** functions | In‑place arithmetic |
| unary `-` | **member** | Negates the rational |
| `== !=` | **member** | Comparison |
| `++` (prefix) | **member** | Increment numerator (just for demo) |
| `++` (postfix) | **member** | Same as prefix but returns the old value |
| `<<` (ostream) | **friend** | Output the rational as `numerator/denominator` |
| `>>` (istream) | **friend** | Input the rational from `numerator/denominator` |

```cpp
#include <iostream>
#include <numeric>   // std::gcd
#include <stdexcept> // std::invalid_argument

// ---------------------------------------------------------------------------
//  Rational number class with operator overloads
// ---------------------------------------------------------------------------
class Rational {
public:
    // ---- Constructors ----------------------------------------------------
    Rational(int num = 0, int den = 1) : numerator(num), denominator(den) {
        normalize();
    }

    // ---- Arithmetic operators (member) ---------------------------------
    Rational operator+(const Rational& rhs) const {
        return Rational(numerator * rhs.denominator + rhs.numerator * denominator,
                        denominator * rhs.denominator);
    }
    Rational operator-(const Rational& rhs) const {
        return Rational(numerator * rhs.denominator - rhs.numerator * denominator,
                        denominator * rhs.denominator);
    }
    Rational operator*(const Rational& rhs) const {
        return Rational(numerator * rhs.numerator,
                        denominator * rhs.denominator);
    }
    Rational operator/(const Rational& rhs) const {
        if (rhs.numerator == 0)
            throw std::invalid_argument("division by zero");
        return Rational(numerator * rhs.denominator,
                        denominator * rhs.numerator);
    }

    // ---- Compound assignment operators (member) -------------------------
    Rational& operator+=(const Rational& rhs) {
        *this = *this + rhs;
        return *this;
    }
    Rational& operator-=(const Rational& rhs) {
        *this = *this - rhs;
        return *this;
    }
    Rational& operator*=(const Rational& rhs) {
        *this = *this * rhs;
        return *this;
    }
    Rational& operator/=(const Rational& rhs) {
        *this = *this / rhs;
        return *this;
    }

    // ---- Unary minus -----------------------------------------------------
    Rational operator-() const { return Rational(-numerator, denominator); }

    // ---- Increment operators (prefix & postfix) -------------------------
    // prefix ++ : increments numerator
    Rational& operator++() { // ++r
        ++numerator;
        normalize();
        return *this;
    }
    // postfix ++ : returns old value
    Rational operator++(int) { // r++
        Rational tmp(*this);
        ++(*this);            // reuse prefix
        return tmp;
    }

    // ---- Comparison operators (member) ----------------------------------
    bool operator==(const Rational& rhs) const {
        return numerator == rhs.numerator && denominator == rhs.denominator;
    }
    bool operator!=(const Rational& rhs) const { return !(*this == rhs); }

    // ---- Friend stream operators ----------------------------------------
    friend std::ostream& operator<<(std::ostream& os, const Rational& r);
    friend std::istream& operator>>(std::istream& is, Rational& r);

private:
    int numerator;
    int denominator;

    // Reduce fraction to simplest form and keep denominator positive
    void normalize() {
        if (denominator == 0)
            throw std::invalid_argument("denominator cannot be zero");

        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }

        int g = std::gcd(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }
};

// ---------------------------------------------------------------------------
//  Stream insertion (<<)
// ---------------------------------------------------------------------------
std::ostream& operator<<(std::ostream& os, const Rational& r) {
    os << r.numerator << '/' << r.denominator;
    return os;
}

// ---------------------------------------------------------------------------
//  Stream extraction (>>)
// ---------------------------------------------------------------------------
std::istream& operator>>(std::istream& is, Rational& r) {
    int n = 0, d = 1;
    char sep = '\0';

    // Expect "numerator/denominator"
    is >> n >> sep >> d;
    if (sep != '/' || !is) {
        is.setstate(std::ios::failbit);
        return is;
    }

    r = Rational(n, d); // will normalize
    return is;
}

// ---------------------------------------------------------------------------
//  Demo: use of the overloaded operators
// ---------------------------------------------------------------------------
int main() {
    Rational a(1, 2);   // 1/2
    Rational b(3, 4);   // 3/4

    std::cout << "a = " << a << "\n";
    std::cout << "b = " << b << "\n";

    // Arithmetic
    std::cout << "a + b = " << a + b << "\n";
    std::cout << "a - b = " << a - b << "\n";
    std::cout << "a * b = " << a * b << "\n";
    std::cout << "a / b = " << a / b << "\n";

    // Compound assignment
    Rational c = a;
    c += b;
    std::cout << "c after += : " << c << "\n";

    // Unary minus
    std::cout << "-a = " << -a << "\n";

    // Increment operators
    std::cout << "++a = " << ++a << "\n"; // prefix
    std::cout << "a++ = " << a++ << "\n"; // postfix, prints old value
    std::cout << "now a = " << a << "\n";

    // Comparison
    std::cout << "a == b ? " << (a == b) << "\n";
    std::cout << "a != b ? " << (a != b) << "\n";

    // Input
    Rational d;
    std::cout << "Enter a rational number (format: n/d): ";
    std::cin >> d;
    if (std::cin)
        std::cout << "You entered: " << d << "\n";
    else
        std::cerr << "Invalid input.\n";

    return 0;
}
```

### What you’ll see

Running the program will produce something like:

```
a = 1/2
b = 3/4
a + b = 5/4
a - b = -1/4
a * b = 3/8
a / b = 2/3
c after += : 5/4
- a = -1/2
++a = 3/2
a++ = 3/2
now a = 5/2
a == b ? 0
a != b ? 1
Enter a rational number (format: n/d): 7/8
You entered: 7/8
```

The key take‑away is that **operator overloading lets you write expressions that look natural for your types** (e.g., `a + b`, `c *= d`, `++a`, `std::cout << a`) while keeping the underlying implementation clean and type‑safe.
